using WAID.Health;namespace WAID.Application.Services;public interface IPredictiveHealthRepository{Task SaveAsync(PredictiveHealthReport report,CancellationToken token);Task<PredictiveHealthReport?> GetLatestAsync(CancellationToken token);}public sealed class PredictiveHealthEngine(IPredictiveHealthModel model,IPredictiveHealthRepository repository,TimeProvider time){public async Task<PredictiveHealthReport> AnalyzeAsync(IReadOnlyList<HealthSnapshot> snapshots,CancellationToken token){var ordered=snapshots.OrderBy(x=>x.CapturedAtUtc).ToArray();var predictions=Enum.GetValues<PredictiveRiskKind>().Select(kind=>model.Predict(kind,Series(kind,ordered),TimeSpan.FromDays(14))).ToArray();var report=new PredictiveHealthReport(Guid.NewGuid(),time.GetUtcNow(),TransparentTrendPredictor.Version,predictions);await repository.SaveAsync(report,token);return report;}private static IReadOnlyList<PredictiveObservation> Series(PredictiveRiskKind kind,IReadOnlyList<HealthSnapshot> snapshots)=>snapshots.Select(s=>new PredictiveObservation(s.CapturedAtUtc,Value(kind,s),$"health:{s.Id}")).ToArray();private static double Value(PredictiveRiskKind k,HealthSnapshot s)=>k switch{PredictiveRiskKind.StorageWear=>Numeric(s,"wearPercent"),PredictiveRiskKind.ThermalTrend=>Numeric(s,"temperatureC"),PredictiveRiskKind.CrashRate=>Count(s,"BSOD","CRASH"),PredictiveRiskKind.MemoryInstability=>Count(s,"MEMORY","RESOURCE_EXHAUSTION"),PredictiveRiskKind.UpdateFailures=>Count(s,"UPDATE","CBS_CORRUPTION"),PredictiveRiskKind.PerformanceDecline=>100-s.Health.Performance,_=>0};private static double Numeric(HealthSnapshot s,string key)=>s.Findings.SelectMany(x=>x.Evidence).Where(x=>x.Key.Equals(key,StringComparison.OrdinalIgnoreCase)&&double.TryParse(x.Value,System.Globalization.CultureInfo.InvariantCulture,out _)).Select(x=>double.Parse(x.Value,System.Globalization.CultureInfo.InvariantCulture)).DefaultIfEmpty(0).Max();private static int Count(HealthSnapshot s,params string[] terms)=>s.Findings.Count(x=>terms.Any(t=>x.Code.Contains(t,StringComparison.OrdinalIgnoreCase)));}